def page_count(total_items, per_page):
    """Number of pages needed to show all items, with a partial final page counted.
    Zero items means zero pages."""
    if total_items == 0:
        return 0
    elif total_items % per_page == 0:
        return total_items // per_page
    else:
        return total_items // per_page + 1

def windows(items, size):
    """Every consecutive run of exactly `size` elements, in order.
    Fewer items than `size` gives an empty list."""
    if len(items) < size:
        return []
    result = []
    for i in range(len(items) - size + 1):
        result.append(items[i:i+size])
    return result

def between(value, low, high):
    """True when value lies strictly between low and high, touching neither end."""
    return low < value < high

def nth_from_end(items, n):
    """The nth element counting back from the end, where n=1 is the last element."""
    if not items or n <= 0:
        return None

    length = len(items)

    if n > length:
        return None

    return items[length - n]

def overlap(a_start, a_end, b_start, b_end):
    """True when two half-open intervals [start, end) share at least one point."""
    return a_start < b_end and b_start < a_end

def truncate_words(text, limit):
    words = text.split()
    if len(words) <= limit:
        return text
    else:
        truncated = ' '.join(words[:limit])
        return truncated + '...'

def bytes_human(n):
    """Format a byte count with one decimal using 1024 steps: 1024 -> '1.0 KB',
    1023 -> '1023.0 B', 1048576 -> '1.0 MB'."""
    for x in ['B', 'KB', 'MB', 'GB', 'TB']:
        if n < 1024.0:
            return "%3.1f %s" % (n, x)
        n /= 1024.0

def insert_sorted(items, value):
    """Insert into a sorted list, placing the value AFTER any equal values."""
    index = 0
    while index < len(items) and items[index] <= value:
        index += 1
    items.insert(index, value)

def backoff(attempts, base):
    """The delay before each retry, doubling each time and starting at `base`.
    One entry per attempt."""
    if attempts == 0:
        return base
    elif attempts == 1:
        return base * 2
    elif attempts == 2:
        return base * 4
    elif attempts == 3:
        return base * 8
    else:
        return base * (2 ** (attempts - 3))

def percentile(values, p):
    """Nearest-rank percentile of a non-empty list: the value at rank ceil(p/100 * n),
    counting from 1 in the sorted order."""
    if not values:
        return None
    values = sorted(values)
    n = len(values)
    rank = ceil(p / 100 * n)
    if rank > n:
        return values[-1]
    if rank == n:
        return values[-1]
    return values[rank - 1]

def clip_exclusive(index, length):
    """Clip an index into the valid positions of a sequence of `length` items."""
    return max(0, min(index, length - 1))

def columns(items, n):
    result = [[] for _ in range(n)]
    for i, item in enumerate(items):
        col_index = i % n
        result[col_index].append(item)
    return result

def countdown(start):
    """Every whole number from `start` down to 1, in order. Zero or less gives nothing."""
    if start <= 0:
        return
    while start > 0:
        print(start)
        start -= 1

def trim_to_fit(words, width):
    """Take words from the front while the joined line stays within `width` characters,
    counting the single spaces between them."""
    result = []
    current_line = ""
    current_width = 0
    for word in words:
        if current_width + len(word) + (len(result) > 0) <= width:
            if len(result) > 0:
                current_line += " "
            current_line += word
            current_width += len(word) + (len(result) > 0)
            result.append(word)
        else:
            break
    return result

def progress(done, total, width):
    """How many cells of a bar `width` wide should be filled, rounded down.
    A finished job fills every cell; zero total fills none."""
    if total == 0:
        return 0
    return int(width * (done / total))
